from openpyxl import load_workbook
from pathlib import Path
path = Path('/root/nasa_budget_recovered.xlsx')
wb = load_workbook(path, data_only=False)
missing = []
errors = []
for sheet in wb.worksheets:
    for row in sheet.iter_rows():
        for cell in row:
            if cell.value == '???': missing.append(f'{sheet.title}!{cell.coordinate}')
            if isinstance(cell.value, str) and cell.value.startswith('#'):
                errors.append(f'{sheet.title}!{cell.coordinate}={cell.value}')
print('missing', missing)
print('errors', errors)
print('recovered', {f'{s}!{c}': wb[s][c].value for s, cells in {
    'Budget by Directorate': ['K5','F8','B9','E10','K10','C12'],
    'YoY Changes (%)': ['D7','B9','F9'],
    'Directorate Shares (%)': ['F5','B10'],
    'Growth Analysis': ['E4','E5','B7','B8'],
}.items() for c in cells})
